// gen_fpu_tables.cpp -- emit rtl/fpu_vec/fpu_vec_tables.svh: the coefficient ROMs of the shared FIPR/FSCA/FSRRA
// datapath, derived from the model tables by the SAME tables the C references use (fsca/sh4_fsca.h, fsrra/sh4_fsrra_words.h).
//   FSCA (17 entries, node folded to 0..16):  C0 26b, C1F 23b + E1 (shift 3-e1), C3 12b; square reuses complementary C1F/E1
//   FSRRA (34 entries = parity*17+node):       C0 27b, REC1 23b + E1, REC2 = 14b FIXED-POINT square field, REC3 = 9b cubic field
// Build: g++ -O2 -std=c++17 gen_fpu_tables.cpp -o /tmp/gen && /tmp/gen > ../../../rtl/fpu_vec/fpu_vec_tables.svh
#include <cstdio>
#include <cstdint>
#include "../sh4_fsca.h"
#include "../../fsrra/sh4_fsrra_words.h"
int main() {
    printf("// fpu_vec_tables.svh -- GENERATED by model/fsca/tools/gen_fpu_tables.cpp, do not edit.\n");
    printf("// FSCA: 17 sine-table entries (node folded to 0..16). FSRRA: 34 entries, index = parity*17 + node.\n");
    printf("// FSCA fields: C0 = 26-bit fixed-point sine at the centre (2^-26 grid); C1F = 23-bit linear field, E1 = its\n");
    printf("//   octave (aligner shift from the product register = 3 - E1); C3 = 12-bit cubic field (recoded as C3 << 5,\n");
    printf("//   aligner shift 6); square reuses complementary C1F/E1 (shift 7 - E1). S/K are compatibility aliases.\n");
    printf("// FSRRA fields: C0 27-bit; REC1 23-bit normalised linear field with octave E1 (shift 6 - E1); REC2 = 14-bit\n");
    printf("//   FIXED-POINT square field (recoded as REC2 << 9, aligner shift 9, no exponent); REC3 = 9-bit fixed-point cubic\n");
    printf("//   field (recoded as REC3 << 8; shift 7 on the final product).  Bit-exact: model/fsrra/tools/rr14_exact.cpp.\n\n");
    // Hardware-natural organisation: every field is a function of sin(m*pi/32).  Word(m), m = 0..16:
    //   C0(m)                 : the sine centre field of word m
    //   L(m), E(m), Q(m)      : linear / cubic fields = C1F, E1, C3 of model entry 16-m  (cos(n) = sin(16-n))
    // One FSCA reads word r and word 16-r (r = node[3:0]) and uses ALL fields of both: sine takes {C0,L} from one
    // and {L,Q} from the other, cosine the reverse.  ROM A[r] = Word(r), ROM B[r] = Word(16-r): two 16-word ROMs,
    // directly addressed, swapped by the quadrant's low bit.  Word 0 is all zeros, Word 16 is the saturated "1.0".
    printf("localparam int FSCA_N = 16;\n");
    for (int rom = 0; rom < 2; rom++) { const char* R = rom ? "B" : "A";
        auto W = [&](int r) { return rom ? 16 - r : r; };
        printf("localparam logic [25:0] FSCA_%s_C0 [FSCA_N] = '{", R); for (int r = 0; r < 16; r++) printf("26'd%lld%s", (long long)sh4_fsca_rom[W(r)].c0, r < 15 ? ", " : "};\n");
        printf("localparam logic [22:0] FSCA_%s_L [FSCA_N] = '{", R);  for (int r = 0; r < 16; r++) printf("23'h%06llx%s", (long long)sh4_fsca_rom[W(r)].l, r < 15 ? ", " : "};\n");
        printf("localparam logic [1:0] FSCA_%s_E [FSCA_N] = '{", R);   for (int r = 0; r < 16; r++) printf("2'd%d%s", sh4_fsca_rom[W(r)].e, r < 15 ? ", " : "};\n");
        printf("localparam logic [11:0] FSCA_%s_Q [FSCA_N] = '{", R);  for (int r = 0; r < 16; r++) printf("12'h%03llx%s", (long long)sh4_fsca_rom[W(r)].q, r < 15 ? ", " : "};\n");
        printf("localparam logic [22:0] FSCA_%s_S [FSCA_N] = FSCA_%s_L; // legacy selector alias\n", R, R);
        printf("localparam logic [1:0] FSCA_%s_K [FSCA_N] = FSCA_%s_E; // legacy selector alias\n", R, R); }
    printf("localparam logic [22:0] FSCA_KC = 23'h%06llx;\n\n", (long long)SH4_FSCA_KC);

    // FSRRA: the ROM words of the bit-exact model (fsrra/sh4_fsrra_words.h, fsrra/tools/rr14_exact.cpp)
    printf("localparam int FSRRA_N = 34;\n");
    for (int i = 0; i < 34; i++) { const FsrraWord& w = FSRRA_WORDS[i];
        if (w.REC1 >= (1 << 23) || w.C2F >= (1 << 14) || w.C3F >= (1 << 9) || w.C0 >= (1ll << 27) || w.E1 > 3) { fprintf(stderr, "field overflow at %d\n", i); return 1; } }
    printf("localparam logic [26:0] FSRRA_C0 [FSRRA_N] = '{"); for (int i = 0; i < 34; i++) printf("27'd%lld%s", (long long)FSRRA_WORDS[i].C0, i < 33 ? ", " : "};\n");
    printf("localparam logic [22:0] FSRRA_REC1 [FSRRA_N] = '{"); for (int i = 0; i < 34; i++) printf("23'h%06x%s", FSRRA_WORDS[i].REC1, i < 33 ? ", " : "};\n");
    printf("localparam logic [1:0] FSRRA_E1 [FSRRA_N] = '{"); for (int i = 0; i < 34; i++) printf("2'd%d%s", FSRRA_WORDS[i].E1, i < 33 ? ", " : "};\n");
    printf("localparam logic [13:0] FSRRA_REC2 [FSRRA_N] = '{"); for (int i = 0; i < 34; i++) printf("14'd%d%s", FSRRA_WORDS[i].C2F, i < 33 ? ", " : "};\n");
    printf("localparam logic [8:0] FSRRA_REC3 [FSRRA_N] = '{"); for (int i = 0; i < 34; i++) printf("9'd%d%s", FSRRA_WORDS[i].C3F, i < 33 ? ", " : "};\n");
    return 0; }
